package com.mushafi.app;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;import java.io.*;
/** Independent opt-out reminders; one pending alarm, validated delivery, no duplicate alerts. */
public final class DailyReminderScheduler {
 public static final String ACTION="com.mushafi.app.DAILY_REMINDER",CHANNEL="daily_reminders_v1";
 private static final int REQUEST=9180;private static JSONObject content;
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("daily_reminders",0);}
 public static synchronized JSONObject content(Context c)throws Exception{if(content==null){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getAssets().open("daily-reminders.json")){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}content=new JSONObject(out.toString("UTF-8"));}return content;}
 static boolean enabled(Context c,String kind){return prefs(c).getBoolean("consent",false);}
 static List<DailyReminderPlan.Event> events(Context c,long now){List<DailyReminderPlan.Event> list=DailyReminderPlan.fixed(now,TimeZone.getDefault());PrayerSettings s=PrayerSettings.load(c);if(s.json.optBoolean("confirmed"))for(int d=-1;d<=8;d++)try{Calendar date=PrayerCalculator.day(s,now,d);if(date.get(Calendar.DAY_OF_WEEK)==Calendar.FRIDAY){long maghrib=PrayerCalculator.calculate(s,date).getLong("maghrib");list.add(new DailyReminderPlan.Event("fridayDua",maghrib-15*60000L));}}catch(Exception ignored){}Collections.sort(list,(a,b)->Long.compare(a.at,b.at));return list;}
 static PendingIntent pending(Context c,DailyReminderPlan.Event e){Intent i=new Intent(c,DailyReminderReceiver.class).setAction(ACTION);if(e!=null)i.putExtra("at",e.at).putExtra("kind",e.kind);return PendingIntent.getBroadcast(c,REQUEST,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void channel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,UiLocale.text(c,"أدعية وتذكيرات يومية"),NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription(UiLocale.text(c,"الدعاء وأذكار الصباح والمساء وتذكيرات الجمعة"));((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
 public static synchronized void schedule(Context c){try{boolean permission=PrayerScheduler.notifications(c);if(!prefs(c).contains("consent")&&(prefs(c).contains("next")||prefs(c).contains("sent")||prefs(c).contains("dua")))prefs(c).edit().putBoolean("consent",permission).putBoolean("enrolled",true).putBoolean("lastPermission",permission).commit();if(prefs(c).getBoolean("enrolled",false)){if(permission&&!prefs(c).getBoolean("lastPermission",permission))prefs(c).edit().putBoolean("consent",true).apply();prefs(c).edit().putBoolean("lastPermission",permission).apply();}channel(c);AlarmManager alarm=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);long previousAt=prefs(c).getLong("next",0);String previousKind=prefs(c).getString("nextKind","");alarm.cancel(pending(c,null));prefs(c).edit().remove("error").remove("next").remove("nextKind").apply();if(!enabled(c,"dua")||!PrayerScheduler.notifications(c)||!PrayerScheduler.channelEnabled(c,CHANNEL))return;long now=System.currentTimeMillis();if(previousAt>0&&previousAt<=now&&now-previousAt<=120000)deliver(c,new Intent(ACTION).putExtra("at",previousAt).putExtra("kind",previousKind));Set<String> sent=prefs(c).getStringSet("sent",Collections.emptySet());for(DailyReminderPlan.Event e:events(c,now)){if(e.at<=now||!enabled(c,e.kind)||sent.contains(e.id))continue;if(PrayerScheduler.exact(c))alarm.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,e.at,pending(c,e));else alarm.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,e.at,pending(c,e));prefs(c).edit().putLong("next",e.at).putString("nextKind",e.kind).apply();break;}}catch(Exception e){prefs(c).edit().putString("error","تعذر جدولة التذكيرات؛ راجع صلاحيات الإشعارات والمنبّهات").apply();}}
 public static synchronized void deliver(Context c,Intent intent){long now=System.currentTimeMillis(),at=intent.getLongExtra("at",0);String kind=intent.getStringExtra("kind"),id=kind+"|"+at;if(!Arrays.asList(DailyReminderPlan.KINDS).contains(kind)||at>now+2000||now-at>10*60000L||!enabled(c,kind)||!PrayerScheduler.notifications(c)||!PrayerScheduler.channelEnabled(c,CHANNEL))return;boolean valid=false;for(DailyReminderPlan.Event e:events(c,now))if(e.id.equals(id)){valid=true;break;}if(!valid)return;Set<String> sent=new HashSet<>(prefs(c).getStringSet("sent",Collections.emptySet()));if(sent.contains(id))return;try{JSONObject data=content(c),item=null;String title,body,itemId="";if(kind.equals("dua")||kind.equals("fridayDua")){JSONArray pool=data.getJSONArray("pool");int index=kind.equals("dua")?DailyReminderPlan.duaIndex(at,TimeZone.getDefault(),pool.length()):DailyReminderPlan.fridayIndex(at,TimeZone.getDefault(),pool.length());item=pool.getJSONObject(index);itemId=item.getString("id");title=kind.equals("dua")?"دعاء يطمئن به قلبك":"دعاء قبل مغرب الجمعة";body=item.getString("text")+"\n"+item.getString("reference");}else if(kind.equals("salawat")){title="الصلاة على النبي ﷺ";body=data.getJSONObject("salawat").getString("text")+"\nالأحزاب ٥٦";}else if(kind.equals("morning")){title="أذكار الصباح";body="ابدأ صباحك بذكر الله، وخصّص وقتًا لأذكار الصباح.";}else if(kind.equals("evening")){title="أذكار المساء";body="اختم نهارك بذكر الله، وخذ وقتًا لأذكار المساء.";}else{title="ذكرك وقراءتك قبل النوم";body="تذكير بأذكار يومك وقراءة سورة الملك. اختم يومك بالذكر والقرآن.";}
 Intent open=new Intent(c,MainActivity.class).putExtra("dailyReminderKind",kind).putExtra("dailyReminderItem",itemId).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);int code=9200+Arrays.asList(DailyReminderPlan.KINDS).indexOf(kind);PendingIntent pi=PendingIntent.getActivity(c,code,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);AppIdentity.decorate(c,b).setColor(AppIdentity.notificationColor(c)).setContentTitle(UiLocale.text(c,title)).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(pi).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setCategory(Notification.CATEGORY_REMINDER).setWhen(at);if(Build.VERSION.SDK_INT<26)b.setDefaults(Notification.DEFAULT_SOUND);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(code,b.build());for(Iterator<String> it=sent.iterator();it.hasNext();){String key=it.next();try{if(now-Long.parseLong(key.substring(key.indexOf('|')+1))>8*86400000L)it.remove();}catch(Exception e){it.remove();}}sent.add(id);prefs(c).edit().putStringSet("sent",sent).apply();}catch(Exception ignored){}}
 public static synchronized void enter(Context c,long now){TimeZone zone=TimeZone.getDefault();if(!DailyReminderPlan.fridayWindow(now,zone))return;String day=DailyReminderPlan.dateKey(now,zone);int count=day.equals(prefs(c).getString("visitDay",""))?prefs(c).getInt("visits",0)+1:1;prefs(c).edit().putString("visitDay",day).putInt("visits",count).apply();}
 public static synchronized boolean consumeFriday(Context c){long now=System.currentTimeMillis();if(!enabled(c,"fridayGuide")||!PrayerScheduler.notifications(c)||!DailyReminderPlan.fridayWindow(now,TimeZone.getDefault()))return false;String day=DailyReminderPlan.dateKey(now,TimeZone.getDefault());int visit=prefs(c).getInt("visits",0);String token=day+"|"+visit;if(!day.equals(prefs(c).getString("visitDay",""))||!DailyReminderPlan.showVisit(visit)||token.equals(prefs(c).getString("shownVisit","")))return false;prefs(c).edit().putString("shownVisit",token).commit();return true;}
 public static synchronized boolean initializeConsent(Context c){if(!prefs(c).contains("consent")){if(!prefs(c).edit().putBoolean("consent",PrayerScheduler.notifications(c)).putBoolean("enrolled",true).putBoolean("lastPermission",PrayerScheduler.notifications(c)).commit())return false;}schedule(c);return true;}
 public static synchronized boolean setConsent(Context c,boolean enabled){android.content.SharedPreferences.Editor edit=prefs(c).edit().putBoolean("consent",enabled).putBoolean("enrolled",true).putBoolean("lastPermission",PrayerScheduler.notifications(c));for(String k:DailyReminderPlan.KINDS)edit.remove(k);edit.remove("fridayGuide");if(!edit.commit())return false;if(!enabled){NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);for(int i=0;i<DailyReminderPlan.KINDS.length;i++)manager.cancel(9200+i);}schedule(c);return true;}
}
